import type { ChipBarProps } from "../chip-bar.types";

import { useState, useCallback } from "react";

export const useChipBar = ({
  value: valueProp,
  defaultValue,
  onChange,
  selectionMode = "none",
}: ChipBarProps) => {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const isControlled = valueProp !== undefined;
  const value = isControlled ? valueProp : internalValue;

  const setValue = useCallback(
    (newValue: string | string[]) => {
      if (!isControlled) {
        setInternalValue(newValue);
      }
      onChange?.(newValue);
    },
    [isControlled, onChange],
  );

  const handleChipClick = (chipValue: string) => {
    if (selectionMode === "none") {
      return;
    }

    if (selectionMode === "single") {
      setValue(chipValue);
    }

    if (selectionMode === "multiple") {
      const currentValues = (value as string[]) || [];
      const newValues = currentValues.includes(chipValue)
        ? currentValues.filter((v) => v !== chipValue)
        : [...currentValues, chipValue];
      setValue(newValues);
    }
  };

  const chipBarRole = selectionMode === "single" ? "radiogroup" : "group";

  const chipWrapperRole =
    selectionMode === "single" ? "radio" : selectionMode === "multiple" ? "checkbox" : undefined;

  return {
    selectedValue: value,
    handleChipClick,
    chipBarRole,
    chipWrapperRole,
  };
};
